<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaGovernancePressureTestimonyService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:complete-subordinate-persona-governance-pressure-testimony',description:'Consume the Governance pressure testimony authority and seal its trial')]final class SenateCompleteSubordinatePersonaGovernancePressureTestimonyCommand extends Command{public function __construct(private readonly SubordinatePersonaGovernancePressureTestimonyService$s){parent::__construct();}protected function configure():void{$this->addArgument('question-record-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->complete((string)$i->getArgument('question-record-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>GOVERNANCE_PRESSURE_TRIAL_SEALED_PENDING_SECURITY_PRESSURE_QUESTION</info> '.$r['trial_record_id']);return self::SUCCESS;}}
